            readBack.onsuccess = () => {
              const existing =
                (readBack.result as
                  | { generation?: number; seq?: number; wrappedKeyCheckpoint?: string }
                  | undefined) ?? {};
              store.put({ ...existing, seq: value }, nodeId);
            };
            readBack.onerror = () => reject(readBack.error);
            tx.oncomplete = () => resolve();
            tx.onerror = () => reject(tx.error);
          } catch (err) {
            reject(err);
          }
        };
      });
    },
    { nodeId, value }
